#!/usr/bin/env bash
set -euo pipefail
DEST="${ECC_DEST:-$HOME/vhdl_repo/IP_Cores/ECC_Scrubber}"
mkdir -p "$DEST/petalinux_files/recipe/files"
echo ">> destino: $DEST/petalinux_files"
echo "" | base64 -d > "$DEST/petalinux_files/system-user.dtsi"
echo "" | base64 -d > "$DEST/petalinux_files/recipe/ecc-selftest.bb"
echo "" | base64 -d > "$DEST/petalinux_files/recipe/files/ecc_selftest.c"
echo "" | base64 -d > "$DEST/petalinux_files/recipe/files/ecc_fw_on.mem"
echo "" | base64 -d > "$DEST/petalinux_files/recipe/files/ecc_fw_off.mem"
echo "" | base64 -d > "$DEST/gen_fw_variants.py"
echo ">> archivos PetaLinux desplegados:"
find "$DEST/petalinux_files" -type f
echo ">> selftest compila:"
gcc -O2 -Wall "$DEST/petalinux_files/recipe/files/ecc_selftest.c" -o /tmp/_st_check 2>&1 | head -3 && echo "   OK" || echo "   revisar"
